'use strict';

// MODULES //

var isCollection = require( '@stdlib/assert/is-collection' );
var isObject = require( '@stdlib/assert/is-object' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var max = require( '@stdlib/math/base/special/fast/max' );
var getShape = require( '@stdlib/ndarray/shape' );
var resolveGetter = require( '@stdlib/array/base/resolve-getter' );
var expandDimensions = require( '@stdlib/ndarray/base/expand-dimensions' );
var array2tidy = require( '@stdlib/plot/vega/data/tidy/from-array' );
var columns2tidy = require( '@stdlib/plot/vega/data/tidy/from-matrix-columns' );
var nested2tidy = require( '@stdlib/plot/vega/data/tidy/from-nested-array' );
var nestedarrays2tidy = require( '@stdlib/plot/vega/data/tidy/from-nested-arrays' );
var objarray2tidy = require( '@stdlib/plot/vega/data/tidy/from-object-array' );
var objarrays2tidy = require( '@stdlib/plot/vega/data/tidy/from-object-arrays' );
var vector2tidy = require( '@stdlib/plot/vega/data/tidy/from-vector' );
var vectors2tidy = require( '@stdlib/plot/vega/data/tidy/from-vectors' );
var pairedarrays2tidy = require( '@stdlib/plot/vega/data/tidy/from-paired-arrays' );
var pairedcolumns2tidy = require( '@stdlib/plot/vega/data/tidy/from-paired-matrix-columns' );
var pairedvectors2tidy = require( '@stdlib/plot/vega/data/tidy/from-paired-vectors' );
var splitOnKey = require( '@stdlib/plot/vega/data/tidy/split-on-key' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var MAPPING = {
	'x': 'x',
	'y': 'y'
};
var FIELDS = [ 'x', 'y' ];


// FUNCTIONS //

/**
* Returns a data set name.
*
* @private
* @param {NonNegativeInteger} id - data set identifier
* @returns {string} name
*/
function name( id ) { // eslint-disable-line stdlib/no-redeclare
	return 'dataset' + id;
}

/**
* Returns a list of data set names.
*
* @private
* @param {NonNegativeInteger} len - number of names
* @param {NonNegativeInteger} start - starting data set identifier
* @returns {Array<string>} list of names
*/
function names( len, start ) {
	var out;
	var i;

	out = [];
	for ( i = 0; i < len; i++ ) {
		out.push( name( start+i ) );
	}
	return out;
}

/**
* Converts a single argument to a list of tidy data sets.
*
* @private
* @param {(Collection|ndarrayLike)} arg - argument
* @param {Object} mapping - object mapping field names to encoding channels ('x', 'y', and 'z')
* @throws {TypeError} must provide a valid argument
* @returns {Array<DataSet>} list of data sets
*/
function unary( arg, mapping ) {
	var out;
	var tmp;
	var get;
	var sh;
	var v;
	var q;
	var d;
	var s;
	var i;

	out = [];

	// Case: f( ndarray )
	if ( isndarrayLike( arg ) ) {
		sh = getShape( arg );

		// Case: f( vector )
		if ( sh.length === 1 ) {
			// Assume a one-dimensional ndarray with an implicit "x" channel...
			d = vector2tidy( arg, name( 1 ), FIELDS );
			out.push( d );
			return out;
		}
		// Case: f( matrix_columns )
		if ( sh.length === 2 ) {
			// Assume that each column is an independent series with an implicit "x" channel...
			d = columns2tidy( arg, names( sh[ 1 ], 1 ), FIELDS );
			for ( i = 0; i < d.length; i++ ) {
				out.push( d[ i ] );
			}
			return out;
		}
		throw new TypeError( 'invalid argument. First argument must be either a one- or two-dimensional ndarray.' );
	}
	// Case: f( ??? )
	if ( !isCollection( arg ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array-like object, an ndarray, or an array of array-like objects or ndarrays.', arg ) );
	}
	// Case: f( [ ???, ... ] )
	get = resolveGetter( arg );

	// Resolve the first array element:
	v = get( arg, 0 );

	// Case: f( [ vector, vector, ... ] )
	if ( isndarrayLike( v ) ) {
		// Assume a list of one-dimensional ndarrays with an implicit "x" channel...
		for ( i = 0; i < arg.length; i++ ) {
			v = arg[ i ];
			sh = getShape( v );
			if ( sh.length !== 1 ) {
				throw new TypeError( 'invalid argument. First argument must be an array of one-dimensional ndarrays.' );
			}
			d = vector2tidy( v, name( i+1 ), FIELDS );
			out.push( d );
		}
		return out;
	}
	// Case: f( [ [ ??? ], [ ??? ], ... ] )
	if ( isCollection( v ) ) {
		// Resolve the first array element of the nested array:
		get = resolveGetter( v );
		q = get( v, 0 );

		// Case: f( [ [ [...], [...] ], [ [...], [...] ], ... ] )
		if ( isCollection( q ) ) {
			// Assume each nested array is an array of x/y tuples representing a single dataset...
			d = nestedarrays2tidy( arg, names( v.length, 1 ), FIELDS );
			for ( i = 0; i < d.length; i++ ) {
				out.push( d[ i ] );
			}
			return out;
		}
		// Case: f( [ [ {...}, {...} ], [ {...}, {...} ], ... ] )
		if ( isObject( q ) ) {
			// Assume each nested array of objects represents a single dataset...
			d = objarrays2tidy( arg, names( v.length, 1 ), mapping );
			for ( i = 0; i < d.length; i++ ) {
				out.push( d[ i ] );
			}
			return out;
		}
		// Case: f( [ [ primitive, primitive, ... ], ... ] )

		// Assume each nested array represents a single dataset with an implicit "x" channel...
		d = nested2tidy( arg, name( 1 ), FIELDS );
		out.push( d );
		return out;
	}
	// Case: f( [ {...}, {...} ] )
	if ( isObject( v ) ) {
		// Assume a single list of values which may contain multiple datasets grouped according to the "z" channel...
		d = objarray2tidy( arg, name( 1 ), mapping );
		if ( mapping.z ) {
			tmp = splitOnKey( d, mapping.z );
			for ( i = 0; i < tmp.length; i++ ) {
				s = tmp[ i ];
				s.name = name( i+1 );
				out.push( s );
			}
		} else {
			out.push( d );
		}
		return out;
	}
	// Case: f( [ primitive, primitive, ... ] )

	// Assume a single list of y-values with an implicit "x" channel...
	d = array2tidy( arg, name( 1 ), FIELDS );
	out.push( d );
	return out;
}

/**
* Converts two argument to a list of tidy data sets.
*
* @private
* @param {(Array|ndarrayLike)} arg1 - first argument
* @param {(Array|ndarrayLike)} arg2 - second argument
* @throws {TypeError} must provide a valid argument
* @returns {Array<DataSet>} list of data sets
*/
function binary( arg1, arg2 ) {
	var get;
	var out;
	var shx;
	var shy;
	var N;
	var v;
	var d;
	var i;

	// Case: f( ndarray, ??? )
	if ( isndarrayLike( arg1 ) ) {
		shx = getShape( arg1 );

		// Case: f( ndarray, ndarray )
		if ( isndarrayLike( arg2 ) ) {
			if ( shx.length < 1 || shx.length > 2 ) {
				throw new TypeError( 'invalid argument. First argument must be either a one- or two-dimensional ndarray.' );
			}
			// If we were provided a vector for the first argument, expand to a column matrix...
			if ( shx.length === 1 ) {
				// Case: f( vector, ndarray )
				arg1 = expandDimensions( arg1, 1 );
				shx.push( 1 );
			}
			// Assume that each column in the first argument is an "x" vector and each column in the second argument is a "y" vector...
			shy = getShape( arg2 );
			if ( shy.length < 1 || shy.length > 2 ) {
				throw new TypeError( 'invalid argument. Second argument must be either a one- or two-dimensional ndarray.' );
			}
			// Case: f( ndarray, vector )
			if ( shy.length === 1 ) {
				arg2 = expandDimensions( arg2, 1 );
				shy.push( 1 );
			}
			// By this point, we should be equivalent to f( matrix, matrix )...
			N = max( shx[ 1 ], shy[ 1 ] );
			return pairedcolumns2tidy( arg1, arg2, names( N, 1 ), FIELDS );
		}
		if ( shx.length !== 1 ) {
			throw new TypeError( 'invalid argument. First argument must be a one-dimensional ndarray.' );
		}
		// Case: f( vector, [ vector, vector, ... ] )
		if ( isCollection( arg2 ) ) {
			// Assume that each element in the second argument is a "y" vector...
			out = [];
			for ( i = 0; i < arg2.length; i++ ) {
				v = arg2[ i ];
				if ( !isndarrayLike( v ) ) {
					throw new TypeError( format( 'invalid argument. Second argument must be either an ndarray or an array of ndarrays. Value: `%s`.', arg2 ) );
				}
				shy = getShape( v );
				if ( shy.length !== 1 ) {
					throw new TypeError( 'invalid argument. Second argument must be an array of one-dimensional ndarrays.' );
				}
				d = vectors2tidy( [ arg1, v ], name( i+1 ), FIELDS );
				out.push( d );
			}
			return out;
		}
		throw new TypeError( format( 'invalid argument. Second argument must be either an ndarray or an array of ndarrays. Value: `%s`.', arg2 ) );
	}
	// Case: f( ???, ??? )
	if ( !isCollection( arg1 ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array-like object, an ndarray, or an array of array-like objects or ndarrays.', arg1 ) );
	}
	// Case: f( [ ???, ... ], ??? )
	get = resolveGetter( arg1 );

	// Resolve the first array element:
	v = get( arg1, 0 );

	// Case: f( [ ndarray, ... ], ??? )
	if ( isndarrayLike( v ) ) {
		// Case: f( [ ndarray, ... ], ndarray )
		if ( isndarrayLike( arg2 ) ) {
			shy = getShape( arg2 );
			if ( shy.length !== 1 ) {
				throw new TypeError( 'invalid argument. Second argument must be a one-dimensional ndarray.' );
			}
			// Assume that each element in the first argument is an "x" vector...
			out = [];
			for ( i = 0; i < arg1.length; i++ ) {
				v = arg1[ i ];
				if ( !isndarrayLike( v ) ) {
					throw new TypeError( format( 'invalid argument. First argument must be either an ndarray or an array of ndarrays. Value: `%s`.', arg1 ) );
				}
				shx = getShape( v );
				if ( shx.length !== 1 ) {
					throw new TypeError( 'invalid argument. First argument must be an array of one-dimensional ndarrays.' );
				}
				d = vectors2tidy( [ v, arg2 ], name( i+1 ), FIELDS );
				out.push( d );
			}
			return out;
		}
		// Case: f( [ vector, ... ], [ vector, ... ] )
		if ( isCollection( arg2 ) ) {
			N = max( arg1.length, arg2.length );
			return pairedvectors2tidy( arg1, arg2, names( N, 1 ), FIELDS );
		}
		throw new TypeError( format( 'invalid argument. Second argument must be either an ndarray or an array of ndarrays. Value: `%s`.', arg2 ) );
	}
	// Case: f( [ primitive, primitive, ... ], ??? )
	if ( !isCollection( v ) ) {
		// Assume that the first argument is a single list of x-values...
		arg1 = [ arg1 ];
	}
	// Resolve the first array element of the second argument:
	get = resolveGetter( arg2 );
	v = get( arg2, 0 );

	// Case: f( [...], [ primitive, primitive, ... ] )
	if ( !isCollection( v ) ) {
		// Assume that the second argument is a single list of y-values...
		arg2 = [ arg2 ];
	}
	// At this point, both `arg1` and `arg2` should be arrays of arrays, and, more specifically, are assumed to be arrays of arrays representing x/y vectors, respectively...
	N = max( arg1.length, arg2.length );
	return pairedarrays2tidy( arg1, arg2, names( N, 1 ), FIELDS );
}


// MAIN //

/**
* Converts a list of arguments corresponding to `x` and `y` coordinates to a list of tidy data sets.
*
* ## Notes
*
* -   Encoding channels:
*
*     -   **x**: x-coordinate encoding channel.
*     -   **y**: y-coordinate encoding channel.
*     -   **z**: group encoding channel.
*
* -   The `z` encoding channel only applies to arguments which are arrays of objects and is used to split an array of objects into multiple data sets whose elements are grouped according to the values assigned to the corresponding channel field.
*
* @param {Array} args - list of arguments
* @param {Object} channels - object mapping field names to encoding channels ('x', 'y', and 'z')
* @throws {TypeError} first argument must be an array-like object
* @throws {TypeError} second argument must be an object
* @throws {TypeError} must provide valid arguments
* @returns {Array<DataSet>} list of data sets
*
* @example
* // TODO
*/
function args2tidy( args, channels ) {
	var mapping;
	if ( !isCollection( args ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array-like object. Value: `%s`.', args ) );
	}
	if ( arguments.length > 1 ) {
		if ( !isObject( channels ) ) {
			throw new TypeError( format( 'invalid argument. Second argument must be an object. Value: `%s`.', channels ) );
		}
		mapping = channels;

		// TODO: validate channels
	} else {
		mapping = MAPPING;
	}
	if ( args.length === 0 ) {
		return [];
	}
	if ( args.length === 1 ) {
		return unary( args[ 0 ], mapping );
	}
	return binary( args[ 0 ], args[ 1 ] );
}


// EXPORTS //

module.exports = args2tidy;
